class MockPriceService : public PriceService {
 public:
  MOCK_METHOD(Money, price, (const std::string& sku), (const, override));
};

TEST(Checkout, totals_the_canned_price) {
  MockPriceService prices;
  EXPECT_CALL(prices, price("A-1")).WillOnce(Return(Money{9, 99}));
  Checkout checkout(&prices);              // client depends on PriceService
  EXPECT_EQ(checkout.total("A-1", 2), Money{19, 98});
}

