class FakePriceService final : public PriceService {
 public:
  Money price(const std::string& sku) const override {
    auto it = canned_.find(sku);
    if (it == canned_.end()) throw std::out_of_range("unmapped sku: " + sku);
    return it->second;
  }
  std::map<std::string, Money> canned_{{"A-1", Money{9, 99}}};
};

